 const conflict=merge&&<div className="ss-conflict"><p>设置已有更新，你的修改已保留。</p>{merge.conflicts.map(field=><fieldset key={field.key}><legend>{field.label}</legend>{(['current','mine'] as const).map(choice=><label key={choice}><input type="radio" name={'ss-merge-'+field.key} checked={choices[activeSection]?.revision===active?.revision&&choices[activeSection]?.fields[field.key]===choice} onChange={()=>setChoices(previous=>({...previous,[activeSection]:{revision:active!.revision,fields:{...(previous[activeSection]?.revision===active?.revision?previous[activeSection]?.fields:{}),[field.key]:choice}}}))}/><span>{choice==='current'?'当前设置':'我的修改'}：{field[choice]}</span></label>)}</fieldset>)}</div>;
